CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text,role text NOT NULL CHECK(role IN ('admin','user','readonly')),source text NOT NULL DEFAULT 'local' CHECK(source IN ('local','ldap')),active boolean NOT NULL DEFAULT true,ldap_dn text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,family_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE infrastructures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,type text NOT NULL CHECK(type IN ('proxmox','kubernetes','xcpng','citrix','vmware')),endpoint text NOT NULL,credentials_encrypted text NOT NULL,status text NOT NULL DEFAULT 'pending',last_sync timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),infrastructure_id uuid NOT NULL REFERENCES infrastructures ON DELETE CASCADE,external_id text NOT NULL,name text NOT NULL,state text NOT NULL,host text NOT NULL,cpus integer NOT NULL DEFAULT 0,memory_mb bigint NOT NULL DEFAULT 0,kind text,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(infrastructure_id,external_id));
CREATE TABLE ldap_config(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),config_encrypted text NOT NULL,active boolean NOT NULL DEFAULT false,last_sync timestamptz);
CREATE TABLE webhooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,url text NOT NULL,method text NOT NULL DEFAULT 'POST' CHECK(method IN ('POST','GET','PUT')),headers_encrypted text,events text[] NOT NULL,active boolean NOT NULL DEFAULT true,secret_encrypted text,retry_count integer NOT NULL DEFAULT 3,timeout integer NOT NULL DEFAULT 30,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),webhook_id uuid REFERENCES webhooks ON DELETE CASCADE,event text NOT NULL,status_code integer,error text,duration_ms integer,attempt integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,token_hash text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,scopes text[] NOT NULL,expires_at timestamptz,last_used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backup_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,type text NOT NULL CHECK(type IN ('vm','infrastructure','full')),targets uuid[] NOT NULL DEFAULT '{}',schedule text NOT NULL,retention_days integer NOT NULL DEFAULT 30,storage_type text NOT NULL,storage_config_encrypted text NOT NULL,compression boolean NOT NULL DEFAULT true,encryption boolean NOT NULL DEFAULT false,encryption_password_encrypted text,notify_on_complete boolean NOT NULL DEFAULT true,notify_on_failure boolean NOT NULL DEFAULT true,active boolean NOT NULL DEFAULT true,last_run timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backup_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid REFERENCES backup_jobs ON DELETE SET NULL,status text NOT NULL CHECK(status IN ('running','completed','failed')),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,duration_seconds double precision,backup_size_bytes bigint,backup_path text,manifest jsonb,error_message text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,backup_path text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,status text NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plugins(id text PRIMARY KEY,name text NOT NULL,version text NOT NULL,description text,author text,entry_point text NOT NULL,config jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT false,installed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE maintenance_config(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),active boolean NOT NULL DEFAULT false,message text NOT NULL DEFAULT 'Mantenimiento programado',allowed_ips inet[] NOT NULL DEFAULT '{}',scheduled_start timestamptz,scheduled_end timestamptz);
INSERT INTO maintenance_config(id) VALUES(1);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_id uuid,action text NOT NULL,resource text,ip inet,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit logs are append-only'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_logs FOR EACH STATEMENT EXECUTE FUNCTION prevent_audit_mutation();
CREATE INDEX idx_tokens_user ON api_tokens(user_id);
CREATE INDEX idx_refresh_family ON refresh_tokens(family_id);
CREATE INDEX idx_webhooks_active ON webhooks(active);
CREATE INDEX idx_backup_jobs_active ON backup_jobs(active);
CREATE INDEX idx_backup_history_job ON backup_history(job_id);
CREATE INDEX idx_vms_infra ON vms(infrastructure_id);
CREATE INDEX idx_audit_time ON audit_logs(created_at DESC);
INSERT INTO schema_migrations(version) VALUES('001_schema.sql');
